mapper.insert:
insert into CHB_PRD_PERIODYIELD(SEQNO, FPROD_ID, PROD_ID, CHANGE_DATE, CHANG_TYPE, PROD_VALUE, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK,UNIT_VALUE_TOTAL,CCY) select SEQNO, FPROD_ID, PROD_ID, CHANGE_DATE, CHANG_TYPE, PROD_VALUE, ORG_CODE, DEPT_CODE, STATUS, REV_DATE, DATA_SOURCE, UPDATE_USER, UPDATE_TIME, CREATE_USER, CREATE_TIME, REMARK,UNIT_VALUE_TOTAL,CCY from ( select TEMP.* from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.changeDate,jdbcType=TIMESTAMP} CHANGE_DATE, #{item.changType,jdbcType=VARCHAR} CHANG_TYPE, #{item.prodValue,jdbcType=DECIMAL} PROD_VALUE, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, NOW() CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.unitValueTotal,jdbcType=DECIMAL} UNIT_VALUE_TOTAL, #{item.ccy,jdbcType=VARCHAR} ccy FROM DUAL
) TEMP where not exists (select 1 from CHB_PRD_PERIODYIELD CII where CII.PROD_ID = TEMP.PROD_ID AND DATE_FORMAT(CII.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(TEMP.CHANGE_DATE,'%Y-%m-%d') AND CII.CHANG_TYPE = TEMP.CHANG_TYPE) ) de ;
UPDATE CHB_PRD_PERIODYIELD as A, ( select PROD_VALUE, UNIT_VALUE_TOTAL, ORG_CODE, DEPT_CODE, REV_DATE, STATUS, REMARK, UPDATE_USER, UPDATE_TIME, CCY from ( select TEMP.* from (
SELECT #{item.seqno,jdbcType=CHAR} SEQNO, #{item.fprodId,jdbcType=VARCHAR} FPROD_ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.changeDate,jdbcType=TIMESTAMP} CHANGE_DATE, #{item.changType,jdbcType=VARCHAR} CHANG_TYPE, #{item.prodValue,jdbcType=DECIMAL} PROD_VALUE, #{item.orgCode,jdbcType=VARCHAR} ORG_CODE, #{item.deptCode,jdbcType=VARCHAR} DEPT_CODE, #{item.status,jdbcType=VARCHAR} STATUS, #{item.revDate,jdbcType=TIMESTAMP} REV_DATE, #{item.dataSource,jdbcType=VARCHAR} DATA_SOURCE, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, NOW() UPDATE_TIME, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, NOW() CREATE_TIME, #{item.remark,jdbcType=VARCHAR} REMARK, #{item.unitValueTotal,jdbcType=DECIMAL} UNIT_VALUE_TOTAL, #{item.ccy,jdbcType=VARCHAR} ccy FROM DUAL
) TEMP ) de ) AS B set A.* = B.* where exists (select 1 from CHB_PRD_PERIODYIELD CII where CII.PROD_ID = TEMP.PROD_ID AND DATE_FORMAT(CII.CHANGE_DATE,'%Y-%m-%d') = DATE_FORMAT(TEMP.CHANGE_DATE,'%Y-%m-%d') AND CII.CHANG_TYPE = TEMP.CHANG_TYPE);
